import type {
  ProfileCandidate,
  ProfileObservation,
} from '../../types/design-profile';

type SelectedReference = Omit<ProfileCandidate, 'observation'> & {
  observation: ProfileObservation | null;
  reason: string;
};
type ContextField = { label: string; value: string };

const MAX_CONTEXT_BYTES = 1_500;
const ELLIPSIS = '…';

const shareBudget = (sizes: number[], budget: number): number[] => {
  const allocations = sizes.map(() => 0);
  const ordered = sizes
    .map((size, index) => ({ size, index }))
    .sort((a, b) => a.size - b.size);
  let remaining = budget;
  ordered.forEach(({ size, index }, position) => {
    const allowance = Math.floor(remaining / (ordered.length - position));
    allocations[index] = Math.min(size, allowance);
    remaining -= allocations[index];
  });
  return allocations;
};

const shorten = (text: string, budget: number): string => {
  if (Buffer.byteLength(text) <= budget) return text;
  const available = budget - Buffer.byteLength(ELLIPSIS);
  if (available < 0) return '';
  let size = 0;
  let result = '';
  for (const character of text) {
    const bytes = Buffer.byteLength(character);
    if (size + bytes > available) break;
    result += character;
    size += bytes;
  }
  return result + ELLIPSIS;
};

const referenceFields = ({
  reference,
  observation,
  sources,
  reason,
}: SelectedReference): ContextField[] => {
  const fields = [
    { label: 'Reference', value: reference.title },
    {
      label: 'Sources',
      value: sources.map((source) => source.title).join(', '),
    },
    ...(observation
      ? [{ label: 'Evidence', value: observation.evidence }]
      : []),
    { label: 'Relevance', value: reason },
    ...(observation
      ? [{ label: 'Description', value: observation.description }]
      : []),
  ];
  if (reference.note)
    fields.push({
      label: 'User note for this direction',
      value: reference.note,
    });
  if (reference.variant) {
    const { projectId, sessionId, variantId } = reference.variant;
    fields.push({
      label: 'Saved direction',
      value: `${projectId}/${sessionId}:${variantId}`,
    });
  }
  return fields;
};

const renderReference = (fields: ContextField[], budget: number): string => {
  const labels = fields.map(({ label }) => `${label}: `);
  const overhead = Buffer.byteLength(`\n${labels.join('\n')}\n`);
  const allocations = shareBudget(
    fields.map(({ value }) => Buffer.byteLength(value)),
    budget - overhead,
  );
  return `\n${fields.map(({ value }, index) => `${labels[index]}${shorten(value, allocations[index])}`).join('\n')}\n`;
};

export const selectionContext = (references: SelectedReference[]): string => {
  const fields = references.map(referenceFields);
  const sizes = fields.map((reference) =>
    reference.reduce(
      (size, { label, value }) =>
        size + Buffer.byteLength(`${label}: ${value}\n`),
      Buffer.byteLength('\n'),
    ),
  );
  const allocations = shareBudget(sizes, MAX_CONTEXT_BYTES);
  return fields
    .map((reference, index) => renderReference(reference, allocations[index]))
    .join('');
};
